353		if len(diffs) != 1 || !diffs[0].Since.Equal(t4) {
354			t.Fatalf("since should restart: %+v", diffs)
355		}
356		// 离线和重复上报不刷新差异时间
357		if err := s.SetOffline("dev-1"); err != nil {
358			t.Fatal(err)
359		}
