# 未提供本次独立验收的执行回执；本脚本尚未在控制角色中执行。
# 后续：宿主在两侧独立封存副本执行，保存原始退出码、stdout、stderr。
# 适配仅处理公开 Go 接口的命名、参数顺序、整数类型和存储位置类型。
import pathlib
import subprocess
import sys
import tempfile

GO = r'''
package acceptance

import (
    "encoding/json"
    "fmt"
    "io"
    "os"
    "path/filepath"
    "reflect"
    "sort"
    "strings"
    "sync"
    "testing"
    "time"
    shadow "github.com/descikazuyq/device-shadow/shadow"
)

type client struct { v reflect.Value }
type state struct {
    ID, Version string
    Online bool
    Revision uint64
    Desired, Reported json.RawMessage
}
type entry struct {
    Path string
    DExists, RExists bool
    D, R json.RawMessage
    Since time.Time
}
type record struct {
    ID, Operator string
    At time.Time
    Revision uint64
    Before, After json.RawMessage
}
type snapshot struct { State state; Diff []entry; Audit []record }

func apiKind() string { return reflect.TypeOf(shadow.Open).Out(0).Elem().Name() }
func storagePath(home string) string {
    switch apiKind() {
    case "Store": return filepath.Join(home, "shadow-store.json")
    case "Shadow": return filepath.Join(home, "shadow.json")
    default: panic("unsupported advertised Open return type")
    }
}
func openClient(home string) (*client, error) {
    location := home
    if apiKind() == "Shadow" {
        if err := os.MkdirAll(home, 0700); err != nil { return nil, err }
        location = storagePath(home)
    }
    s, err := shadow.Open(location)
    if err != nil { return nil, err }
    return &client{reflect.ValueOf(s)}, nil
}
func (s *client) invoke(names string, args ...any) []reflect.Value {
    for _, name := range strings.Split(names, "|") {
        m := s.v.MethodByName(name)
        if !m.IsValid() { continue }
        if m.Type().NumIn() != len(args) { panic("adapter argument count: " + name) }
        in := make([]reflect.Value, len(args))
        for i, arg := range args {
            v := reflect.ValueOf(arg)
            if !v.Type().ConvertibleTo(m.Type().In(i)) { panic("adapter argument type: " + name) }
            in[i] = v.Convert(m.Type().In(i))
        }
        return m.Call(in)
    }
    panic("advertised method absent: " + names)
}
func callError(r []reflect.Value) error {
    v := r[len(r)-1]
    if v.IsNil() { return nil }
    return v.Interface().(error)
}
func number(v reflect.Value) uint64 {
    if v.Kind() == reflect.Int64 { return uint64(v.Int()) }
    return v.Uint()
}
func rawField(v reflect.Value) json.RawMessage { return json.RawMessage(v.Bytes()) }
func (s *client) register(id, version string) error { return callError(s.invoke("Register|RegisterDevice", id, version)) }
func (s *client) close() error { return callError(s.invoke("Close")) }
func (s *client) offline(id string) error { return callError(s.invoke("SetOffline|Offline", id)) }
func (s *client) desired(id string, rev uint64, op string, at time.Time, config json.RawMessage) (uint64, error) {
    var r []reflect.Value
    if apiKind() == "Store" { r = s.invoke("UpdateDesired", id, op, at, rev, config) } else { r = s.invoke("UpdateDesired", id, rev, op, at, config) }
    return number(r[0]), callError(r)
}
func (s *client) report(id string, seq uint64, at time.Time, version string, config json.RawMessage) error {
    return callError(s.invoke("Report", id, seq, at, version, config))
}
func (s *client) get(id string) (state, error) {
    r := s.invoke("Get|Device", id)
    if err := callError(r); err != nil { return state{}, err }
    v := r[0]
    return state{v.FieldByName("DeviceID").String(), v.FieldByName("Version").String(), v.FieldByName("Online").Bool(), number(v.FieldByName("Revision")), rawField(v.FieldByName("Desired")), rawField(v.FieldByName("Reported"))}, nil
}
func (s *client) diff(id string) ([]entry, error) {
    r := s.invoke("Diff|Diffs", id)
    if err := callError(r); err != nil { return nil, err }
    out := make([]entry, r[0].Len())
    for i := range out {
        v := r[0].Index(i)
        e := entry{Path: v.FieldByName("Path").String(), Since: v.FieldByName("Since").Interface().(time.Time)}
        if v.FieldByName("DesiredExists").IsValid() {
            e.DExists = v.FieldByName("DesiredExists").Bool()
            e.RExists = v.FieldByName("ReportedExists").Bool()
            e.D = rawField(v.FieldByName("Desired"))

