			BatchSize:   dc.BatchSize,
			WindowStart: dc.WindowStart,
			WindowEnd:   dc.WindowEnd,
			Deadline:    dc.Deadline,
			LastTime:    dc.LastTime,
			Status:      dc.Status,
			Ended:       dc.Ended,
			EndedAt:     dc.EndedAt,
