				DeviceID: dd.DeviceID,
				Batch:    dd.Batch,
				Status:   dd.Status,
				Phase:    dd.Phase,
				Reason:   dd.Reason,
				At:       dd.At,
				Download: decodeOp(dd.Download),
				Install:  decodeOp(dd.Install),
