				return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
			}
			if _, ok := c.index[dr.DeviceID]; !ok {
				return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
			}
