// diskVersion 是升级版本登记的磁盘格式。
type diskVersion struct {
	Target      string   `json:"target"`
	AllowedFrom []string `json:"allowedFrom"`
}

// diskCampaign 是活动的磁盘格式，设备按提交次序保存。
type diskCampaign struct {
	ID          string     `json:"id"`
