159	// 版本字符串精确匹配；列表不能为空、不能含空串、不能包含目标版本。
160	// 目标版本重复登记时返回 ErrVersionExists 并保留原记录。
161	func (s *Store) RegisterUpgrade(targetVersion string, allowedFrom []string) error {
162		s.mu.Lock()
163		defer s.mu.Unlock()
164		if err := s.checkOpen(); err != nil {
165			return err
166		}
167		if targetVersion == "" {
168			return ErrInvalidVersion
169		}
170		if err := validateAllowedFrom(targetVersion, allowedFrom); err != nil {
171			return err
172		}
173		if _, ok := s.versions[targetVersion]; ok {
174			return fmt.Errorf("%w: %s", ErrVersionExists, targetVersion)
175		}
176		from := append([]string(nil), allowedFrom...)
177		return s.commit(func() error {
178			s.versions[targetVersion] = &versionState{Target: targetVersion, AllowedFrom: from}
179			return nil
180		})
181	}
182	
183	func validateAllowedFrom(target string, allowedFrom []string) error {
184		if len(allowedFrom) == 0 {
185			return fmt.Errorf("%w: list is empty", ErrInvalidVersionList)
186		}
187		for _, v := range allowedFrom {
188			if v == "" {
189				return fmt.Errorf("%w: contains empty version", ErrInvalidVersionList)
190			}
191			if v == target {
192				return fmt.Errorf("%w: contains target version %s", ErrInvalidVersionList, target)
193			}
194		}
195		return nil
196	}
