298	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
299	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
300		for id, c := range s.campaigns {
301			if id == excludeCampaign || c.Ended {
302				continue
303			}
304			if _, ok := c.index[deviceID]; ok {
305				return true
306			}
307		}
308		return false
309	}
