324	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
325	//
326	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
327	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
328	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion。
329	// 已领取但未完成的操作再次查询时返回同一标识，不要求在线或位于窗口内。
330	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
331	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
332	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
333		s.mu.Lock()
334		defer s.mu.Unlock()
335		if err := s.checkOpen(); err != nil {
336			return nil, err
337		}
338		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
339		if err != nil {
340			return nil, err
341		}
342		if at.IsZero() {
343			return nil, ErrInvalidTime
344		}
345		if at.Before(c.LastTime) {
346			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
347		}
348		var op *Operation
349		var reject error
350		err = s.commit(func() error {
351			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
352			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
353			if !at.Before(c.Deadline) {
354				c.LastTime = at
355				s.applyTimeout(c, at)
356				reject = ErrCampaignEnded
357				return nil
358			}
359			if c.Ended {
360				// 纯拒绝路径：不推进时间基线，不改状态。
361				reject = ErrCampaignEnded
362				return nil
363			}
364			if isTerminal(cd.Status) {
365				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
366				return nil
367			}
368			c.LastTime = at
369			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
370			if out := outstandingOp(c, cd); out != nil {
371				op = out
372				return nil
373			}
374			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
375			if !s.batchOpen(c, cd) {
376				return nil
377			}
378			if !s.devices[deviceID].Online {
379				return nil // 离线保留待办，上线后继续
380			}
381			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
382				return nil // 窗口外不派发新操作；窗口为 [start, end)
383			}
384			if !cd.Download.Claimed {
385				// 首次领取下载前再次检查当前版本。
386				current := s.devices[deviceID].Version
387				if !containsString(s.versions[c.Target].AllowedFrom, current) {
388					s.failDevice(c, cd, StageDownload,
389						fmt.Sprintf("version %s is not compatible with target %s", current, c.Target), at)
390					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
391					return nil
392				}
393				cd.Download.Claimed = true
394				cd.Download.ClaimedAt = at
395				cd.Status = DeviceDownloading
396				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
397				return nil
398			}
399			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
400			cd.Install.Claimed = true
401			cd.Install.ClaimedAt = at
402			cd.Status = DeviceInstalling
403			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
404			return nil
405		})
406		if err != nil {
407			return nil, err
408		}
409		if reject != nil {
410			return nil, reject
411		}
412		return op, nil
413	}
414	
415	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
416	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
417		switch {
418		case cd.Download.Claimed && !cd.Download.HasResult:
419			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
420		case cd.Install.Claimed && !cd.Install.HasResult:
421			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
422		default:
423			return nil
424		}
425	}
426	
427	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
428	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
429		for _, other := range c.Devices {
430			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
431				return false
432			}
433		}
434		return true
435	}
436	
437	// SubmitResult 接收设备提交的操作结果。
438	//
439	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
440	// 改用不同结果、跳过未领取阶段、提交其他设备的操作、活动结束后的新结果
441	// 均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
442	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
443	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
444	// 影子与活动在同一次持久化中更新。普通设备上报不经过本方法，也不会推进活动。
445	func (s *Store) SubmitResult(res OperationResult) error {
446		s.mu.Lock()
447		defer s.mu.Unlock()
448		if err := s.checkOpen(); err != nil {
449			return err
450		}
451		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
452		if err != nil {
453			return err
454		}
455		if res.At.IsZero() {
456			return ErrInvalidTime
457		}
458		if res.At.Before(c.LastTime) {
459			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
460		}
461		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
462		var stage string
463		var op *opState
464		switch res.OperationID {
465		case cd.Download.ID:
466			stage, op = StageDownload, &cd.Download
467		case cd.Install.ID:
468			stage, op = StageInstall, &cd.Install
469		default:
470			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
471		}
472		// 已接受结果：相同结果幂等（活动结束后仍有效），不同结果冲突。
473		if op.HasResult {
474			if resultMatches(op, res) {
475				return nil
476			}
477			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
478		}
479		if !op.Claimed {
480			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段。
481			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
482		}
483		if !res.Success && res.Reason == "" {
484			return ErrInvalidReason
485		}
486		if res.Success && stage == StageInstall {
487			if err := s.validateInstallReport(res); err != nil {
488				return err
489			}
490		}
491		var reject error
492		err = s.commit(func() error {
493			// 到达截止时间：未结束设备全部超时并落盘；新结果（非重复）不再接受。
494			if !res.At.Before(c.Deadline) {
495				c.LastTime = res.At
496				s.applyTimeout(c, res.At)
497				reject = ErrCampaignEnded
498				return nil
499			}
500			if c.Ended {
501				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
502				reject = ErrCampaignEnded
503				return nil
504			}
505			if isTerminal(cd.Status) {
506				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
507				return nil
508			}
509			c.LastTime = res.At
510			op.HasResult = true
511			op.Success = res.Success
512			op.Reason = res.Reason
513			op.At = res.At
514			if !res.Success {
515				s.failDevice(c, cd, stage, res.Reason, res.At)
516				return nil
517			}
518			if stage == StageDownload {
519				cd.Status = DeviceReady
520				cd.Phase = StageInstall
521			} else {
522				// 安装成功：附带上报与活动同时更新、一起持久化。
523				s.applyInstallReport(cd.DeviceID, res, res.At)
524				op.ResultSeq = res.Seq
525				op.ResultVersion = res.Version
526				op.ResultConfig = cloneRaw(res.Config)
527				cd.Status = DeviceSucceeded
528				cd.Phase = StageInstall
529				cd.Reason = ""
530				cd.At = res.At
531			}
532			c.Results = append(c.Results, ResultRecord{
533				DeviceID:    cd.DeviceID,
534				OperationID: op.ID,
535				Stage:       stage,
536				Success:     true,
537				Version:     op.ResultVersion,
538				At:          res.At,
539			})
540			s.settle(c, res.At)
541			return nil
542		})
543		if err != nil {
544			return err
545		}
546		return reject
547	}
548	
549	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
550	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
551	// 使活动结束后的重复提交仍然有效。
552	func resultMatches(op *opState, res OperationResult) bool {
553		if op.Success != res.Success || op.Reason != res.Reason {
554			return false
555		}
556		if op.Success && op.ResultSeq != 0 {
557			return op.ResultSeq == res.Seq &&
558				op.ResultVersion == res.Version &&
559				rawEqual(op.ResultConfig, res.Config)
560		}
561		return true
562	}
563	
564	// validateInstallReport 按现有上报规则校验安装成功附带的设备上报，
565	// 且版本必须等于目标版本。只校验，不改状态。
566	func (s *Store) validateInstallReport(res OperationResult) error {
567		d := s.devices[res.DeviceID]
568		if res.Seq == 0 {
569			return fmt.Errorf("%w: report sequence", ErrInvalidReport)
570		}
571		if res.Version == "" {
572			return fmt.Errorf("%w: report version", ErrInvalidReport)
573		}
574		if res.Version != s.campaigns[res.CampaignID].Target {
575			return fmt.Errorf("%w: version %s", ErrInvalidReport, res.Version)
576		}
577		if _, err := validateConfig(res.Config); err != nil {
578			return fmt.Errorf("%w: config", ErrInvalidReport)
579		}
580		switch {
581		case res.Seq < d.LastSeq:
582			return fmt.Errorf("%w: stale sequence", ErrInvalidReport)
583		case res.Seq == d.LastSeq:
584			if !(res.Version == d.Version && res.At.Equal(d.LastReportTime) && rawEqual(res.Config, d.Reported)) {
585				return fmt.Errorf("%w: sequence conflict", ErrInvalidReport)
586			}
587		}
588		return nil
589	}
590	
591	// applyInstallReport 按 Report 的既有规则写入影子（调用方已校验）。
592	func (s *Store) applyInstallReport(deviceID string, res OperationResult, at time.Time) {
593		d := s.devices[deviceID]
594		if res.Seq == d.LastSeq {
595			// 相同序号的完全重复上报：影子不变，只随活动一起落盘。
596			return
597		}
598		d.Reported = cloneRaw(res.Config)
599		d.Version = res.Version
600		d.Online = true
601		d.LastSeq = res.Seq
602		d.LastReportTime = at
603		d.refreshDiff(at)
604	}
605	
606	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
607	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
608	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
609		cd.Status = DeviceFailed
610		cd.Phase = phase
611		cd.Reason = reason
612		cd.At = at
613		c.Results = append(c.Results, ResultRecord{
614			DeviceID:    cd.DeviceID,
615			OperationID: opIDFor(cd, phase),
616			Stage:       phase,
617			Success:     false,
618			Reason:      reason,
619			At:          at,
620		})
621		for _, other := range c.Devices {
622			if other.Batch > cd.Batch && !isTerminal(other.Status) {
623				other.Status = DeviceSkipped
624				other.Phase = pendingPhase(other)
625				other.Reason = "not executed: previous batch failed"
626				other.At = at
627			}
628		}
629		s.settle(c, at)
630	}
631	
632	func opIDFor(cd *campaignDevice, phase string) string {
633		if phase == StageInstall {
634			return cd.Install.ID
635		}
636		return cd.Download.ID
637	}
638	
639	// pendingPhase 返回设备尚未完成的阶段。
640	func pendingPhase(cd *campaignDevice) string {
641		if cd.Install.Claimed {
642			return StageInstall
643		}
644		return StageDownload
645	}
646	
647	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
648	// 已有终态保持不变，活动记为失败并结束。
649	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
650		if c.Ended {
651			return
652		}
653		for _, cd := range c.Devices {
654			if isTerminal(cd.Status) {
655				continue
656			}
657			cd.Status = DeviceTimeout
658			cd.Phase = pendingPhase(cd)
659			cd.Reason = "deadline exceeded"
660			cd.At = at
661		}
662		c.Status = CampaignFailed
663		c.Ended = true
664		c.EndedAt = at
665	}
666	
667	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
668	func (s *Store) settle(c *campaignState, at time.Time) {
669		allSucceeded := true
670		for _, cd := range c.Devices {
671			if !isTerminal(cd.Status) {
672				return
673			}
674			if cd.Status != DeviceSucceeded {
675				allSucceeded = false
676			}
677		}
678		c.Ended = true
679		c.EndedAt = at
680		if allSucceeded {
681			c.Status = CampaignSucceeded
682		} else {
683			c.Status = CampaignFailed
684		}
685	}
686	
687	func isTerminal(status string) bool {
688		switch status {
689		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped:
690			return true
691		default:
692			return false
693		}
694	}
695	
696	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
697	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
698	// 未到截止时间或活动已结束时为空操作。
699	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
700		s.mu.Lock()
701		defer s.mu.Unlock()
702		if err := s.checkOpen(); err != nil {
703			return err
704		}
705		c, err := s.lookupCampaign(campaignID)
706		if err != nil {
707			return err
708		}
709		if at.IsZero() {
710			return ErrInvalidTime
711		}
712		if at.Before(c.LastTime) {
713			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
714		}
715		if c.Ended {
716			return nil
717		}
718		if at.Before(c.Deadline) {
719			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
720			return s.commit(func() error { c.LastTime = at; return nil })
721		}
722		return s.commit(func() error {
723			c.LastTime = at
724			s.applyTimeout(c, at)
725			return nil
726		})
727	}
728	
729	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
730		if campaignID == "" {
731			return nil, ErrInvalidCampaignID
732		}
733		c, ok := s.campaigns[campaignID]
734		if !ok {
735			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
736		}
737		return c, nil
738	}
739	
740	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
741		c, err := s.lookupCampaign(campaignID)
742		if err != nil {
743			return nil, nil, err
744		}
745		if deviceID == "" {
746			return nil, nil, ErrInvalidDeviceID
747		}
748		i, ok := c.index[deviceID]
749		if !ok {
750			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
751		}
752		return c, c.Devices[i], nil
753	}
754	
755	// DeviceStatusView 是一台设备在活动中的状态快照。
756	type DeviceStatusView struct {
757		DeviceID string
758		Batch    int
759		// Status 取 Device* 状态常量。
760		Status string
761		// Phase 是设备当前停留或失败的阶段（download/install）。
762		Phase string
763		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
764		Reason string
765		// At 是进入当前状态的时间。
766		At time.Time
767		// DownloadID/InstallID 是两个阶段操作的稳定标识。
768		DownloadID string
769		InstallID  string
770	}
771	
772	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
773	type BatchView struct {
774		Index   int
775		Devices []DeviceStatusView
776	}
777	
778	// CampaignView 是分批升级活动的只读快照。
779	type CampaignView struct {
780		ID            string
781		Operator      string
782		TargetVersion string
783		CreatedAt     time.Time
784		BatchSize     int
785		WindowStart   time.Time
786		WindowEnd     time.Time
787		Deadline      time.Time
788		// Status 取 Campaign* 状态常量。
789		Status  string
790		Ended   bool
791		EndedAt time.Time
792		// Devices 按提交次序给出每台设备的状态。
793		Devices []DeviceStatusView
794		// Batches 按批次号分组，保留设备提交次序。
795		Batches []BatchView
796		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
797		Results []ResultRecord
798	}
799	
800	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
801	// 失败或超时原因及结果历史。返回数据为独立副本。
802	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
803		s.mu.Lock()
804		defer s.mu.Unlock()
805		if err := s.checkOpen(); err != nil {
806			return CampaignView{}, err
807		}
808		c, err := s.lookupCampaign(campaignID)
809		if err != nil {
810			return CampaignView{}, err
811		}
812		v := CampaignView{
813			ID:            c.ID,
814			Operator:      c.Operator,
815			TargetVersion: c.Target,
816			CreatedAt:     c.CreatedAt,
817			BatchSize:     c.BatchSize,
818			WindowStart:   c.WindowStart,
819			WindowEnd:     c.WindowEnd,
820			Deadline:      c.Deadline,
821			Status:        c.Status,
822			Ended:         c.Ended,
823			EndedAt:       c.EndedAt,
824			Results:       make([]ResultRecord, len(c.Results)),
825		}
826		copy(v.Results, c.Results)
827		for _, cd := range c.Devices {
828			dv := DeviceStatusView{
829				DeviceID:   cd.DeviceID,
830				Batch:      cd.Batch,
831				Status:     cd.Status,
832				Phase:      cd.Phase,
833				Reason:     cd.Reason,
834				At:         cd.At,
835				DownloadID: cd.Download.ID,
836				InstallID:  cd.Install.ID,
837			}
838			v.Devices = append(v.Devices, dv)
839			for len(v.Batches) <= cd.Batch {
840				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
841			}
842			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
843		}
844		return v, nil
845	}
846	
847	// DeviceWork 是设备当前版本与待执行操作的查询结果。
848	type DeviceWork struct {
849		DeviceID string
850		Version  string
851		Online   bool
852		// CampaignID 是设备当前所在的未结束活动；没有时为空。
853		CampaignID string
854		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
855		Pending *Operation
856		// PendingClaimed 表示 Pending 是否已领取（未领取的安装仍须等维护窗口）。
857		PendingClaimed bool
858	}
859	
860	// GetDeviceWork 查询设备当前版本及其待执行操作。
861	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
862		s.mu.Lock()
863		defer s.mu.Unlock()
864		if err := s.checkOpen(); err != nil {
865			return DeviceWork{}, err
866		}
867		d, err := s.lookup(deviceID)
868		if err != nil {
869			return DeviceWork{}, err
870		}
871		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
872		for id, c := range s.campaigns {
873			if c.Ended {
874				continue
875			}
876			i, ok := c.index[deviceID]
877			if !ok {
878				continue
879			}
880			cd := c.Devices[i]
881			w.CampaignID = id
882			if out := outstandingOp(c, cd); out != nil {
883				w.Pending = out
884				w.PendingClaimed = true
885			} else if !isTerminal(cd.Status) {
886				kind := StageDownload
887				id := cd.Download.ID
888				if cd.Download.HasResult {
889					kind, id = StageInstall, cd.Install.ID
890				}
891				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
892				w.PendingClaimed = false
893			}
894			break
895		}
896		return w, nil
897	}
898	
899	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
900	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
901		s.mu.Lock()
902		defer s.mu.Unlock()
903		if err := s.checkOpen(); err != nil {
904			return nil, err
905		}
906		out := make([]VersionSpec, 0, len(s.versions))
907		for _, v := range s.versions {
908			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
909		}
910		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
911		return out, nil
912	}
